#include <bits/stdc++.h>
using namespace std;

int main(){
    int N;
    cin>>N;
    string S,T;
    cin>>S>>T;
    string ans="Yes";
    for(int i=0;i<N;i++){
        if(T[i]!=S[i]&&T[i]!='*'){
            ans="No";
        }
    }
    cout<<ans<<"\n";
}
N=int(input())
S=input()
T=input()
if all(t in s+"*" for s,t in zip(S,T)):
    ans="Yes"
else:
    ans="No"
print(ans)
